  ('baf58126-ef80-5ad2-a9d4-f8fc0a06e09f', null, (select id from public.skills where slug = 'decimal-operations'), null, 'hard',
   $q$A rectangular garden is 3.4 meters long and 2.5 meters wide. What is the area of the garden in square meters?$q$, $q$[{"text":"6.2 square meters","is_correct":false,"misconception_token":"multiplied-matching-places-only"},{"text":"8.5 square meters","is_correct":true},{"text":"11.8 square meters","is_correct":false,"misconception_token":"found-perimeter-instead-of-area"},{"text":"5.9 square meters","is_correct":false,"misconception_token":"added-length-and-width"}]$q$::jsonb, $q$8.5 square meters$q$, $q$Area is length times width: $3.4 \times 2.5$. Multiply $34 \times 25 = 850$; there are two decimal places in all, so the area is $8.50$, or $8.5$ square meters. The answer 6.2 square meters multiplies only $3 \times 2$ and $0.4 \times 0.5$ and leaves out the cross parts.$q$, 'draft', null)
